// Generated by vibelang from plugins/factory/src/feeds.ts; the migrate flow writes it again with each batch.
/** The core's index of a repository's feed documents: every document whose name has no `/`. */
export const INDEX = "core/feeds";
/** One on-demand feed document, by name: `transcript/<lane>`, `diff/<commit>`, `report/...`. */
export const DOCUMENT = "core/feed";
/** The items of one index document, one row per element with an id: what the action strip answers. */
export const ASKS = "core/feed-items";
/** Smithers' own agent runs of a repository (docs/features/fleet.md#queries), which Agents lists beside the lanes. */
export const RUNS = "core/agent-runs";
/** The document whose items are the decisions that wait on a maintainer. */
export const DECISIONS = "for_will";
/** `owner/name`, as feeds key a repository. */
export const repoOf = (repository) => `${repository.owner}/${repository.name}`.toLowerCase();
/** The feeds over `host`'s reads. */
export const feedsOf = (host) => ({
    index: (repository) => host.query(INDEX, { repo: repoOf(repository) }),
    document: (repository, name) => host.query(DOCUMENT, { repo: repoOf(repository), name }),
    asks: (repository) => host.query(ASKS, { repo: repoOf(repository), name: DECISIONS }),
    select: (ask) => host.select({ query: ASKS, key: ask.key, params: { repo: ask.repo, name: ask.document } }),
    runs: (repository) => host.query(RUNS, { repo: repoOf(repository) }),
});
